mapper.update:
UPDATE my_plan
SET
    title = #{title},
    description = #{description},
    start_day = #{startTime},
    end_day = #{endTime},
    updated_at = NOW(),
    total_member = #{totalMember}
WHERE no = #{no}
  AND user_no = #{userNo}

mapper.delete:
DELETE FROM my_plan
WHERE no = #{planNo}
  AND user_no = #{userNo}

mapper.select:
SELECT COUNT(*)
FROM my_plan
WHERE user_no = #{userNo}
